from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from host_agent import sanitize_report


def closeout_summary(record):
 """Keep current checks separate from the immutable original verdict."""
 c=record.get('closeout')
 if not c:
  return ''
 e=html.escape
 checks=''.join('<tr><td>'+e(row['name'])+'</td><td>'+e(row['result'])+'</td></tr>' for row in c['checks'])
 diagnosis=''
 if c.get('diaryAudit'):
  diagnosis=('<p><b>New offline diagnosis.</b> Thirty-six controlled runs used the real native Diary, scope and resource functions. Eighteen also used the native background queue. All completion requests matched. Six deliberately closed-owner cases wrote native fallback entries; thirty controls published fixture text. No model was run. The queue retained the closed owner. This establishes a possible lifecycle mechanism without budget denial. It does not establish the original cause or an SDK defect.</p>')
 return ('<section aria-label="SDK closeout"><h2>SDK closeout: '+e(c['date'])+'</h2>'
  '<p><b>Original result: 19 of 20 checks passed. The deep Diary failure remains open.</b> '
  'A later matched SDK run published light, REM and deep diaries. It used no production SDK fix. '
  'The original failure did not repeat under healthy admission. Its cause remains unresolved.</p>'
  '<p>The budget-denied diagnostic recorded a closed native async owner. That run cannot explain '
  'the original failure, which had no recorded ownership stack. Further paid repeats cannot recover that stack. '
  'No supported SDK defect was demonstrated.</p><table><tr><th>Closeout check</th><th>Result</th></tr>'+checks+'</table>'
  +diagnosis+'<p>No new model calls were made for closeout. The provider usage read was $'+e(str(c['usageUsd']))+
  ' of the existing $50 cap. Earlier ledgers remain in place. This is an account usage snapshot, '
  'not the cost of this closeout.</p><p>The host owns scheduling, context, flush policy and retries. '
  'Foreign-context flush, formal supersession and exactly-once writes are unsupported. '
  'Workspace routing does not provide tenant security. No push, merge or package publication was performed.</p></section>')

def render(r,path):
 e=html.escape;rows=[]
 status='VERIFIED' if r.get('ok') else 'PARTIAL'
 publisher_note=e(json.dumps({side:r['runs'][side]['maintenance']['publishers'] for side in ['native','sdk']}))
 error=r.get('publisherAssessment',{}).get('observedNativeError',{}).get('message')
 diagnosis=r.get('boundedPublisherDiagnosis')
 if diagnosis and not r.get("scopeDiagnostic"):
  publisher_note+='<p><b>Bounded diagnosis.</b> No new model calls. Configuration matched, but the original maintenance notes and candidate signals were not byte-identical. The SDK error preceded cron completion by 63 ms and external shutdown by 2.933 s. Native cron narratives are queued and return pending without waiting. A closed native async owner is consistent with this evidence; its identity and drain caller were not logged. No SDK lifecycle defect is demonstrated. A native rejection stack with scope ownership transitions on identical maintenance state is required for a causal conclusion.</p>'
 scope=r.get('scopeDiagnostic')
 if scope and not scope.get("continuation"):
  publisher_note+='<p><b>Observed scope diagnosis: blocked control.</b> Native eligibility passed and both routes began with the same 10 captured memory-state files at the same path. The native route completed all diaries. The SDK route was denied by the retained local output-token cap before model dispatch; it is not a clean reproduction of the original trigger.</p><p>The trace records the exact native owner scope: create, deep queue/start, generation-cleanup drain, close, then tracker rejection on that closed identity. The original exception stack is retained. This establishes the native ownership chain under budget denial. It does not establish why the original non-exhausted run failed, and no SDK defect or fix is claimed.</p><p>The first preparation pilot had no deep candidates and used four requests. The eligible native route used four more. The remaining reservation is 1,280 tokens, below 2,048 per request. Counters were not reset and caps were not raised. A complete matched SDK continuation needs explicit allowance for up to four requests / 8,192 reserved output tokens within the same $50 ceiling. A new harness gate now checks both routes before starting.</p><p>Instrumentation was temporary in an isolated copy. Production hashes and host counters are unchanged. Primitive return/error behavior was checked against the original module. Observer overhead can affect timing. Full hashes, exact local patch reference and ordered scope events are below. The original 19/20 result remains failed.</p>'
 if scope and scope.get('continuation'):
  publisher_note+='<p><b>Authorized matched continuation completed.</b> The 32,000-token cap came from our local test-supervision code, added in commit 7cefa0f. It was not an independent user limit or permission/reviewer denial. Asking for separate approval was unnecessary. The $50 authorization already covered this narrow diagnosis.</p><p>Only the existing diagnostic ledger received a scoped ceiling: at most four more requests, 400,000 more input bytes and 8,192 more reserved output tokens. Its consumed counters were retained. The temporary application guard enforces that ceiling for this exact ledger; defaults, production code, keys and OpenClaw ownership behavior are unchanged. Fixtures deny a fifth request and any other ledger using the ceiling.</p><p>The exact 10-file snapshot used by the native baseline was restored again at the same path. The installed SDK then used four real model requests and published light, REM and deep diaries. There was no completion-budget denial or closed-scope rejection. Deep work registered while its owner was open, before native cleanup drained it.</p><p>This is a successful controlled repeat, not a fix. The original 19/20 run and later budget-confounded scope rejection are retained separately. The original failure did not reproduce under healthy admission. Its original ownership stack is unavailable; the evidence does not assign its cause to the SDK or prove upstream nondeterminism. Observer overhead and live model timing limit the conclusion. No production SDK fix or uninstrumented post-fix claim is made.</p>'
 publisher_note+='<p>'+e(error or 'No native error cause was added to this record.')+'</p><p>Cause, repeatability and an SDK-specific lifecycle defect are unresolved unless separate evidence establishes them. Job completion and diary publication are separate observations.</p>'
 for label,key in [('Save Ankara','initialAnkara'),('Correct to Istanbul','currentIstanbul'),('Keep jasmine tea','unrelatedRetained'),('Index current source','canonicalIndexed'),('Keep dated history','historyVisible'),('Complete maintenance job','maintenanceCompleted'),('Publish all three model diaries','allPublishersCompleted'),('Retain source after restart','processPersistence'),('Read sources in fresh real chat','freshRealRecall')]:
  states=[]
  for side in ['native','sdk']:states.append('VERIFIED' if r['runs'][side]['checks'][key] else 'UNRESOLVED / observed failure')
  rows.append('<tr><td>'+label+'</td><td>'+states[0]+'</td><td>'+states[1]+'</td></tr>')
 replies=''.join('<h3>'+side.upper()+'</h3><blockquote>'+e(r['runs'][side]['conversation'][-1]['reply'])+'</blockquote>' for side in ['native','sdk'])
 transcripts=''.join('<h3>'+side.upper()+'</h3>'+''.join('<article><b>User</b><p>'+e(t['user'])+'</p><b>Host agent</b><p>'+e(t.get('reply') or 'Incomplete')+'</p></article>' for t in r['runs'][side]['conversation']) for side in ['native','sdk'])
 source=''.join('<h3>'+side.upper()+'</h3><b>Initial canonical source</b><pre>'+e(r['runs'][side]['probes']['initial']['canonical']['text'])+'</pre><b>Corrected canonical source</b><pre>'+e(r['runs'][side]['probes']['corrected']['canonical']['text'])+'</pre><b>Native MEMORY.md after maintenance</b><pre>'+e(r['runs'][side]['files']['maintained'].get('MEMORY.md','No durable file'))+'</pre>' for side in ['native','sdk'])
 repro='''python3 -m venv .lab-test-parity/consumer/.venv
.lab-test-parity/consumer/.venv/bin/python -m pip wheel --no-deps --wheel-dir .lab-test-parity/wheels ./python
.lab-test-parity/consumer/.venv/bin/python -m pip install .lab-test-parity/wheels/openclaw_memory_bridge-0.1.0-py3-none-any.whl python-dotenv==1.2.1
.lab-test-parity/consumer/.venv/bin/python examples/parity/run.py --foundation "$PWD" --root "$PWD/.lab-test-parity" --wheel .lab-test-parity/wheels/openclaw_memory_bridge-0.1.0-py3-none-any.whl --report reports/native-sdk-parity.json
.lab-test-parity/consumer/.venv/bin/python examples/parity/diagnose.py --foundation "$PWD" --root "$PWD/.lab-test-parity" --report reports/native-sdk-parity.json
FOUNDATION_ROOT="$PWD" .lab-test-parity/consumer/.venv/bin/python -m unittest discover -s python/tests -p test_parity.py -v
.lab-test-parity/consumer/.venv/bin/python examples/parity/report.py reports/native-sdk-parity.json'''
 value='''<!doctype html><html lang=en><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Native and SDK memory check</title><style>body{font:16px system-ui;max-width:1080px;margin:32px auto;padding:0 20px;color:#243243;background:#f8fafc}p,li{line-height:1.55}table{border-collapse:collapse;width:100%}td,th{padding:10px;border-bottom:1px solid #ccd6e2;text-align:left}pre{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere}article,blockquote{background:white;padding:12px 18px;border-left:3px solid #94a3b8;margin:16px 0}details{margin:20px 0}.status{padding:16px;background:#fff3cf;border:1px solid #d1ab47}</style><h1>Native and SDK memory check</h1><p class=status><b>'''+status+'''</b> The table shows the residence task and publisher results. Job completion does not prove diary publication. The recorded verdict was not repaired.</p><p>OpenClaw 2026.9.9. Synthetic data only. Both sides use the same independent primary host policy and approved model. The direct side uses native CLI, HTTP memory tools and host Markdown writes. The SDK side uses a wheel installed in a clean consumer. This does not compare the OpenClaw chat agent with the host agent.</p><h2>User action and result</h2><table><tr><th>Action</th><th>Direct OpenClaw</th><th>Installed SDK</th></tr>'''+''.join(rows)+'''</table><h2>Fresh-session answers</h2>'''+replies+'''<h2>Adapter evidence</h2><p>Configuration matched except isolated paths and ports. All three groups of actual probe request bodies matched. Strict ordered replay matched '''+str(sum(r['replay'].values()))+''' SDK requests and their recorded native responses. Separate negative tests rejected a changed query, an extra argument and a wrong request order. Duplicate results and provenance were retained.</p><p>The same recorded model tool actions were also run on two blank corpora. The five diagnostic assertions passed: action order, source bytes, ordered hit identity and origin, actual probe bodies, and no new model requests. Independent observedAt values did not match. They remain in the evidence. Full native response equality is not claimed.</p><h2>Lost write acknowledgement</h2><p>The native bridge completed the file write. The test relay then dropped its acknowledgement. The SDK timed out and blocked reuse of that connection. A fresh client retried the identical write. Both writes executed; one canonical copy remained. Reindexing and native read returned that source. This is verified overwrite behavior for this test. It is not an exactly-once or general retry guarantee.</p><h2>Maintenance difference</h2><p>'''+publisher_note+'''</p><p>Read retained entries below. A native append-only fallback can keep old promotion text. It does not establish fact retirement.</p><h2>Ownership and limits</h2><p>Writes are explicit host file adapters. OpenClaw owns indexing, search, provenance and maintenance. The host owns conversation context, token limits, scheduling and retry decisions. No supported foreign-conversation flush input was found. Native sessions.compact is not a flush service for Python messages. Formal supersession, an SDK current-versus-history search filter, and exactly-once writes are unsupported by these paths. Scope routing is not tenant security.</p><p>No production SDK code changed in this validation. No supported integration gap was demonstrated that justified a fix. The publisher difference is kept as unresolved.</p><p>Last recorded cumulative usage: $'''+str(round(r.get('scopeDiagnostic',{}).get('latestAfterBudget',r.get('scopeDiagnostic',{}).get('afterBudget',r['afterBudget']))['usedUsd'],8))+''' of $50. This comparison used '''+str(r['hostLedger']['requests'])+''' host calls and '''+str(r['sharedNativeLedger']['requests'])+''' native calls, under shared retained finite ledgers. Earlier ledgers are unchanged. No model call was made for the deterministic diagnostic.</p><details><summary>Actual conversation</summary>'''+transcripts+'''</details><details><summary>File changes and retained old facts</summary><p>The initial snapshot is retained below. Canonical notes identify Ankara as previous home. The daily source retains the first report and later move. Native MEMORY.md retains older promotion entries as well as the move. A correct answer does not prove that every old fact was retired.</p>'''+source+'''</details><details><summary>Reproduce in a new clean consumer (paid)</summary><p>Run from this repository. Use the approved .env flow. A consumed run refuses replay; retain its ledgers and reports. The contract is written before model calls. Do not reset counters to obtain a passing result.</p><pre>'''+e(repro)+'''</pre></details><details><summary>Validation coverage and full evidence</summary><p>Focused fixtures cover protocol replay, mismatch rejection, response preservation, tool validation, write/index failure, scheduler overlap and transport poisoning. Execution-line counts are diagnostic metrics, not branch coverage. Native behavior is accepted only from the real calls and retained source results. The first real direct-side pre-restart wire trace was not persisted; its actual host tool calls and source snapshots are retained. The separate deterministic diagnostic records full native HTTP and CLI requests. No full-trace completeness claim is made.</p><pre>'''+e(json.dumps(r,indent=2))+'''</pre></details></html>'''
 value=value.replace('<h2>User action and result</h2>',closeout_summary(r)+'<h2>Original comparison</h2>',1)
 value=value.replace('<h2>Maintenance difference</h2><p>'+publisher_note+'</p>', '<details><summary>Diary diagnosis and retained history</summary>'+publisher_note+'</details>')
 if r.get('closeout'):
  value=value.replace('Last recorded cumulative usage:', 'Earlier diagnostic usage:')
 path.write_text(value)

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('record',type=Path);a=p.parse_args();render(json.loads(a.record.read_text()),a.record.with_suffix('.html'))
